async function getXp(sdk: BotSDK, skill: string): Promise<number> {
  const state = sdk.getState();
  if (!state || !state.skills) return 0;
  const sk = state.skills.find((s: any) => s.name.toLowerCase() === skill.toLowerCase());
  return sk ? sk.experience : 0;
}

